package io.github.samlinb.openbone.core;
import java.util.*;
import org.junit.jupiter.api.*;
import io.github.samlinb.openbone.application.*;
import io.github.samlinb.openbone.core.animation.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;
class PhysicsReplayTest {
 static DocumentSnapshot fixture(){var d=new DocumentSnapshot(List.of(new Bone(id(1),"root",null,Transform.IDENTITY,0),new Bone(id(2),"spring",id(1),Transform.IDENTITY,100),new Bone(id(3),"tip",id(2),new Transform(100,0,0,1,1),10)),List.of(),List.of());return d.withConstraints(List.of(PhysicsSolverTest.fixture(List.of(1.,0.,0.,0.,0.)).withParameter(5,0)));}
 @Test void setupIsUntouchedAndDescendantsUsePhysicsMatrices(){var d=fixture();var setup=d.evaluateWorld();var player=new PhysicsPlayer();var clip=d.animations().get(0).id();var first=player.seek(d,clip,1./60,false);double shift=100*PhysicsConstraint.STEP*PhysicsConstraint.STEP;PhysicsSolverTest.near(shift,first.bones().get(id(2)).origin().x());PhysicsSolverTest.near(100+shift,first.bones().get(id(3)).origin().x());assertEquals(setup,d.evaluateWorld());assertEquals(Transform.IDENTITY,d.bone(id(2)).local());assertEquals(5,PhysicsPlayer.duration(d,clip));}
 @Test void emptyAnimationSetStillHasAStaticPhysicsPreview()throws Exception{var d=fixture().withAnimations(List.of());var player=new PhysicsPlayer();assertEquals(5,PhysicsPlayer.duration(d,AnimationClip.DEFAULT_ID));assertTrue(player.seek(d,AnimationClip.DEFAULT_ID,1,false).bones().get(id(2)).origin().x()>0);assertEquals(d,new io.github.samlinb.openbone.io.ProjectCodec().decode(new io.github.samlinb.openbone.io.ProjectCodec().encode(d)));player.invalidate(d.withConstraints(List.of()));assertTrue(player.states().isEmpty());assertEquals(-1,player.frame());}
 @Test void seekingAndTenSequentialReplaysMatchAtEveryTick(){var d=fixture();var clip=d.animations().get(0).id();var baseline=new ArrayList<WorldPose>();for(int run=0;run<10;run++){var player=new PhysicsPlayer();for(int n=0;n<=120;n++){var pose=player.seek(d,clip,n/60.,false);if(run==0)baseline.add(pose);else assertEquals(baseline.get(n),pose);}}for(int n:new int[]{120,3,0,59,10,119})assertEquals(baseline.get(n),new PhysicsPlayer().seek(d,clip,n/60.,false));}
 @Test void repeatedFramePoseLoopAndResetDoNotIntegrateAgain(){var d=fixture();var clip=d.animations().get(0).id();var player=new PhysicsPlayer();var expected=player.seek(d,clip,1,false);long count=player.evaluations();assertEquals(expected,player.seek(d,clip,1,false));assertEquals(count,player.evaluations());var state=player.states();player.seek(d,clip,1+.25/60,false);assertEquals(state,player.states());assertEquals(count,player.evaluations());assertEquals(new PhysicsPlayer().seek(d,clip,0,false),player.seek(d,clip,5,true));assertTrue(player.resets()>=2);player.reset();assertEquals(expected,player.seek(d,clip,1,false));}
 @Test void longFrameIsBoundedAndEditsUndoClearOnlyTransientState(){var d=fixture();var clip=d.animations().get(0).id();var player=new PhysicsPlayer();var doc=new ProjectDocument(d);var before=doc.history().state();player.seek(d,clip,5,false);assertEquals(301,player.evaluations());assertEquals(before,doc.history().state());assertFalse(doc.history().isDirty());assertThrows(IllegalArgumentException.class,()->player.seek(d,clip,601,false));var changed=ModelEdits.editBone(d,id(2),b->b.withLocal(new Transform(10,0,0,1,1)));assertEquals(new PhysicsPlayer().seek(changed,clip,.5,false),player.seek(changed,clip,.5,false));assertEquals(new PhysicsPlayer().seek(d,clip,.5,false),player.seek(d,clip,.5,false));}
 @Test void orderedPhysicsParentIsAppliedBeforeChildConstraint(){var d=fixture();var child=new PhysicsConstraint(id(6),"child",1,true,id(3),List.of(0.,1.,0.,0.,0.),5000,List.of(0.,100.,.9,1.,0.,1.,1.));d=d.withConstraints(List.of(d.constraints().get(0),child));var pose=new PhysicsPlayer().seek(d,d.animations().get(0).id(),.5,false);assertTrue(pose.bones().get(id(3)).origin().y()<0);assertTrue(pose.bones().get(id(3)).origin().x()>100);var ordered=d;assertThrows(IllegalArgumentException.class,()->ordered.withConstraints(List.of(child.withOrder(0),((PhysicsConstraint)ordered.constraints().get(0)).withOrder(1))));}
}
